const checks = await Promise.allSettled([
  tools.exec_command({cmd:"\"$STAMPED_ASSESSMENT_PYTHON\" \"$STAMPED_ASSESSMENT_RUNNER\" check",max_output_tokens:5000,yield_time_ms:30000}),
  tools.exec_command({cmd:"cat \"$STAMPED_ASSESSMENT_VERSION\" && cat \"$STAMPED_DELIVERY_MANIFEST\" && cat \"$STAMPED_OPERATIONAL_MANIFEST\" && cat \"$STAMPED_WORKER_STOP_RECEIPT\" && cat \"$STAMPED_JUDGE_TARGET/judge-target.json\"",max_output_tokens:12000,yield_time_ms:10000})
]); for (let i=0;i<checks.length;i++) text(JSON.stringify({i,...checks[i]}));

