const r=await tools.exec_command({cmd:"$STAMPED_ASSESSMENT_PYTHON - <<'PY'
import hashlib,json,os,pathlib,stat
root=pathlib.Path(os.environ['STAMPED_JUDGE_TARGET'])
man=json.load(open(os.environ['STAMPED_OPERATIONAL_MANIFEST']))
changes=[]; missing=[]; extra=[]
expected={e['path'].removeprefix('content/workspace/'):e for e in man['entries'] if e['path'].startswith('content/workspace/') and e['path']!='content/workspace'}
for rel,e in expected.items():
 p=root/rel
 try: st=p.lstat()
 except FileNotFoundError: missing.append(rel); continue
 kind='file' if stat.S_ISREG(st.st_mode) else 'symlink' if stat.S_ISLNK(st.st_mode) else 'directory' if stat.S_ISDIR(st.st_mode) else 'other'
 if kind!=e['kind']: changes.append({'path':rel,'expected_kind':e['kind'],'actual_kind':kind}); continue
 if kind=='file':
  h=hashlib.sha256(p.read_bytes()).hexdigest()
  if h!=e.get('sha256'): changes.append({'path':rel,'expected_sha256':e.get('sha256'),'actual_sha256':h})
 elif kind=='symlink':
  t=os.readlink(p)
  if t!=e.get('link_target'): changes.append({'path':rel,'expected_target':e.get('link_target'),'actual_target':t})
for p in root.rglob('*'):
 rel=p.relative_to(root).as_posix()
 if rel not in expected and not any(rel.startswith(x+'/') for x in expected if expected[x]['kind']=='directory'): extra.append(rel)
# Count regular file modifications separately allowed only under the three annex keys DB files.
allowed={'.git/annex/keysdb/db','.git/annex/keysdb/db-shm','.git/annex/keysdb/db-wal'}
allowed_changes=[c for c in changes if c['path'] in allowed and 'actual_sha256' in c]
invalid=[c for c in changes if c not in allowed_changes]
result={'capture_sha256':hashlib.sha256(open(os.environ['STAMPED_OPERATIONAL_MANIFEST'],'rb').read()).hexdigest(),'expected_entries':len(expected),'content_differences':changes,'missing':missing,'extra':sorted(extra),'allowed_regular_db_metadata_differences':allowed_changes,'invalid_differences':invalid}
open(os.path.join(os.environ['STAMPED_JUDGE_OUTPUT'],'integrity.json'),'w').write(json.dumps(result,indent=2)+'\n')
print(json.dumps(result,indent=2))
PY",max_output_tokens:3000,yield_time_ms:30000}); text(r.output);

